window.MpiSourceCode = {
  "3": "#define _CRT_SECURE_NO_WARNINGS\r\n#include <cstdio>\r\n#include <windows.h>\r\n\r\n// MPIBegin3.\r\n// Чётный ранг: вводится целое число. Нечётный ранг: вводится вещественное число.\r\n// Результат: удвоенное значение введённого числа.\r\nint main()\r\n{\r\n    SetConsoleOutputCP(CP_UTF8);\r\n\r\n    while (true)\r\n    {\r\n        int rank;\r\n        printf(\"\\nВведите ранг (0, 1, 2, ...; -1 = выход): \");\r\n        if (scanf(\"%d\", &rank) != 1 || rank < 0)\r\n            break;\r\n\r\n        if (rank % 2 == 0)\r\n        {\r\n            int n;\r\n            printf(\"Ранг %d (чётный): введите целое число: \", rank);\r\n            if (scanf(\"%d\", &n) != 1) break;\r\n            printf(\"[MPIBegin3][ранг %d] n = %d, 2*n = %d\\n\", rank, n, 2 * n);\r\n        }\r\n        else\r\n        {\r\n            double x;\r\n            printf(\"Ранг %d (нечётный): введите вещественное число: \", rank);\r\n            if (scanf(\"%lf\", &x) != 1) break;\r\n            printf(\"[MPIBegin3][ранг %d] x = %.2f, 2*x = %.2f\\n\", rank, x, 2 * x);\r\n        }\r\n    }\r\n    return 0;\r\n}",
  "5": "#define _CRT_SECURE_NO_WARNINGS\r\n#include <cstdio>\r\n#include <windows.h>\r\n\r\n// MPIBegin5.\r\n// В каждом процессе дано целое N (> 0) и набор из N чисел.\r\n// Чётный ранг: сумма. Нечётный ранг: среднее арифметическое.\r\nint main()\r\n{\r\n    SetConsoleOutputCP(CP_UTF8);\r\n\r\n    while (true)\r\n    {\r\n        int rank;\r\n        printf(\"\\nВведите ранг (0, 1, 2, ...; -1 = выход): \");\r\n        if (scanf(\"%d\", &rank) != 1 || rank < 0)\r\n            break;\r\n\r\n        int n;\r\n        do\r\n        {\r\n            printf(\"Ранг %d: введите N (> 0): \", rank);\r\n            if (scanf(\"%d\", &n) != 1) return 0;\r\n        } while (n <= 0);\r\n\r\n        double s = 0, x;\r\n        printf(\"Ранг %d: введите %d чисел: \", rank, n);\r\n        for (int i = 0; i < n; i++)\r\n        {\r\n            if (scanf(\"%lf\", &x) != 1) return 0;\r\n            s += x;\r\n        }\r\n\r\n        if (rank % 2 == 0)\r\n            printf(\"[MPIBegin5][ранг %d] N = %d, сумма = %.2f\\n\", rank, n, s);\r\n        else\r\n            printf(\"[MPIBegin5][ранг %d] N = %d, среднее = %.2f\\n\", rank, n, s / n);\r\n    }\r\n    return 0;\r\n}",
  "10": "// MPIBegin10, М. Э. Абрамян. Сборка для Windows, C++17 + Microsoft MPI.\r\n// При обычном запуске собираем ввод для процессов. Ключ --mpi использует mpiexec.\r\n#include <windows.h>\r\n#include <process.h>\r\n#include <mpi.h>\r\n#include <array>\r\n#include <charconv>\r\n#include <iostream>\r\n#include <sstream>\r\n#include <stdexcept>\r\n#include <string>\r\n#include <vector>\r\n\r\nconstexpr int maxLength = 4;\r\nconstexpr int maxRanks = 12;\r\nusing Batch = std::array<int, maxLength>;\r\n\r\nint runMpi(int argc, char** argv) {\r\n    MPI_Init(&argc, &argv);\r\n    MPI_Comm comm = MPI_COMM_WORLD;\r\n    int rank, size;\r\n    MPI_Comm_rank(comm, &rank);\r\n    MPI_Comm_size(comm, &size);\r\n    if (argc != 2 + (size - 1) * (1 + maxLength)) {\r\n        if (rank == 0) std::cerr << \"Неверное число входных наборов.\\n\";\r\n        MPI_Finalize();\r\n        return 1;\r\n    }\r\n\r\n    if (rank == 0) {\r\n        std::vector<int> answer;\r\n        for (int source = 1; source < size; ++source) {\r\n            Batch received{};\r\n            MPI_Status status;\r\n            MPI_Recv(received.data(), maxLength, MPI_INT, source, 0, comm, &status);\r\n\r\n            int count;\r\n            MPI_Get_count(&status, MPI_INT, &count);\r\n            std::cout << \"От ранга \" << source << \" (N = \" << count << \"):\";\r\n            for (int i = 0; i < count; ++i) {\r\n                std::cout << ' ' << received[i];\r\n                answer.push_back(received[i]);\r\n            }\r\n            std::cout << '\\n';\r\n        }\r\n        std::cout << \"Ответ ранга 0:\";\r\n        if (answer.empty()) std::cout << \" (пусто)\";\r\n        for (int value : answer) std::cout << ' ' << value;\r\n        std::cout << std::endl;\r\n    } else {\r\n        // Пусковая часть передаёт каждому рангу N и четыре места для чисел.\r\n        // В MPI-сообщение входят только первые N элементов.\r\n        int offset = 2 + (rank - 1) * (1 + maxLength);\r\n        int n;\r\n        Batch values{};\r\n        try {\r\n            n = std::stoi(argv[offset]);\r\n            if (n < 1 || n > maxLength) throw std::out_of_range(\"N\");\r\n            for (int i = 0; i < n; ++i)\r\n                values[i] = std::stoi(argv[offset + 1 + i]);\r\n        } catch (const std::exception&) {\r\n            MPI_Abort(comm, 2);\r\n            return 2;\r\n        }\r\n\r\n        int packed;\r\n        MPI_Pack_size(n, MPI_INT, comm, &packed);\r\n        int bytes = packed + MPI_BSEND_OVERHEAD;\r\n        std::vector<char> buffer(bytes);\r\n        MPI_Buffer_attach(buffer.data(), bytes);\r\n        MPI_Bsend(values.data(), n, MPI_INT, 0, 0, comm);\r\n        void* released = nullptr;\r\n        MPI_Buffer_detach(&released, &bytes);\r\n    }\r\n    MPI_Finalize();\r\n    return 0;\r\n}\r\n\r\nstruct EndOfInput {};\r\n\r\nstd::string readLine(const std::string& prompt) {\r\n    std::cout << prompt << std::flush;\r\n    std::string line;\r\n    if (!std::getline(std::cin, line) || line == \"q\") throw EndOfInput{};\r\n    return line;\r\n}\r\n\r\nbool strictInt(const std::string& token, int& value) {\r\n    const char* first = token.data();\r\n    const char* last = first + token.size();\r\n    if (first != last && *first == '+') ++first;\r\n    if (first == last || *first == '+') return false;\r\n    auto parsed = std::from_chars(first, last, value);\r\n    return parsed.ec == std::errc{} && parsed.ptr == last;\r\n}\r\n\r\nint processCount() {\r\n    for (;;) {\r\n        std::istringstream input(readLine(\"\\nСколько всего процессов (1..12, -1 для выхода)? \"));\r\n        int count;\r\n        std::string token, extra;\r\n        if ((input >> token) && !(input >> extra) && strictInt(token, count)) {\r\n            if (count == -1) throw EndOfInput{};\r\n            if (count >= 1 && count <= maxRanks) return count;\r\n        }\r\n        std::cout << \"Ошибка: введите одно целое число от 1 до 12 или -1 для выхода.\\n\";\r\n    }\r\n}\r\n\r\nint readBatch(int rank, Batch& values) {\r\n    for (;;) {\r\n        std::istringstream input(readLine(\"Ранг \" + std::to_string(rank) + \" — введите числа: \"));\r\n        int n = 0;\r\n        std::string token;\r\n        bool valid = true;\r\n        while (input >> token) {\r\n            int x;\r\n            if (n >= maxLength) {\r\n                std::cout << \"Ошибка: можно ввести от 1 до 4 чисел. Повторите строку.\\n\";\r\n                valid = false;\r\n                break;\r\n            }\r\n            if (!strictInt(token, x)) {\r\n                std::cout << \"Ошибка: число №\" << n + 1\r\n                          << \" должно быть целым (например, 2). Введено: \\\"\"\r\n                          << token << \"\\\". Повторите строку.\\n\";\r\n                valid = false;\r\n                break;\r\n            }\r\n            values[n++] = x;\r\n        }\r\n        if (valid && n > 0) return n;\r\n        if (valid) std::cout << \"Ошибка: введите от 1 до 4 целых чисел через пробел.\\n\";\r\n    }\r\n}\r\n\r\nint launch(const std::vector<Batch>& batches, const std::vector<int>& lengths) {\r\n    // Абсолютный путь нужен и при запуске из другой папки или с пробелами в пути.\r\n    std::wstring path(32768, L'\\0');\r\n    DWORD length = GetModuleFileNameW(nullptr, path.data(), static_cast<DWORD>(path.size()));\r\n    if (length == 0 || length >= path.size())\r\n        throw std::runtime_error(\"Не удалось определить путь к программе.\");\r\n    path.resize(length);\r\n    std::vector<std::wstring> args = {L\"mpiexec.exe\", L\"-n\", std::to_wstring(batches.size()),\r\n                                      L\"\\\"\" + path + L\"\\\"\", L\"--mpi\"};\r\n    for (size_t rank = 1; rank < batches.size(); ++rank) {\r\n        args.push_back(std::to_wstring(lengths[rank]));\r\n        for (int value : batches[rank]) args.push_back(std::to_wstring(value));\r\n    }\r\n    std::vector<const wchar_t*> pointers;\r\n    for (const auto& arg : args) pointers.push_back(arg.c_str());\r\n    pointers.push_back(nullptr);\r\n    std::cout << std::flush;\r\n    auto code = _wspawnvp(_P_WAIT, L\"mpiexec.exe\", pointers.data());\r\n    if (code == -1) throw std::runtime_error(\"Не удалось запустить mpiexec.exe из Microsoft MPI.\");\r\n    return static_cast<int>(code);\r\n}\r\n\r\nint main(int argc, char** argv) {\r\n    SetConsoleOutputCP(CP_UTF8);\r\n    if (argc >= 2 && std::string(argv[1]) == \"--mpi\") return runMpi(argc, argv);\r\n\r\n    std::cout << \"MPIBegin10. Ранг 0 собирает наборы от остальных рангов.\\n\";\r\n    try {\r\n        while (true) {\r\n            int size = processCount();\r\n            std::vector<Batch> batches(size, Batch{});\r\n            std::vector<int> lengths(size, 0);\r\n            if (size > 1) {\r\n                std::cout << \"Ранг 0 получает данные. Для каждого отправителя введите от 1 до 4 \"\r\n                             \"целых чисел в одной строке. Например: 4 5\\n\";\r\n            }\r\n            for (int rank = 1; rank < size; ++rank)\r\n                lengths[rank] = readBatch(rank, batches[rank]);\r\n            std::cout << \"\\nРанг 0 получил наборы по порядку:\\n\" << std::flush;\r\n            int rc = launch(batches, lengths);\r\n            if (rc != 0) {\r\n                std::cerr << \"Ошибка запуска MPI, код \" << rc << \".\\n\";\r\n                return rc;\r\n            }\r\n        }\r\n    } catch (const EndOfInput&) {\r\n        return 0;\r\n    } catch (const std::exception& error) {\r\n        std::cerr << error.what() << '\\n';\r\n        return 1;\r\n    }\r\n    return 0;\r\n}\r\n",
  "11": "// MPIBegin11. Пересылка вещественных чисел от ранга 0.\r\n#include \"console_mpi.hpp\"\r\nusing namespace console_mpi;\r\n\r\nRow readInput(int, int size, const Rows&) {\r\n    if (size == 1) return {};\r\n    size_t n = size - 1;\r\n    return numbers(\"Ранг 0 — введите \" + std::to_string(n) +\r\n                   \" чисел для рангов 1..\" + std::to_string(n) + \" по порядку: \", n, n, false);\r\n}\r\n\r\nvoid solve(int rank, int size, const Row& row) {\r\n    MPI_Comm comm = MPI_COMM_WORLD;\r\n    if (rank == 0) {\r\n        for (int dest = 1; dest < size; ++dest) {\r\n            double value = unpackReal(row.at(dest - 1));\r\n            MPI_Send(&value, 1, MPI_DOUBLE, dest, 0, comm);\r\n        }\r\n        if (size == 1) std::cout << \"Подчинённых процессов нет.\\n\";\r\n    } else {\r\n        double received;\r\n        MPI_Status status;\r\n        MPI_Recv(&received, 1, MPI_DOUBLE, 0, 0, comm, &status);\r\n        answer(rank, decimal(received));\r\n    }\r\n}\r\n\r\nint main(int argc, char** argv) {\r\n    Task task = {\"MPIBegin11. Пересылка вещественных чисел от ранга 0.\", InputRanks::root, 1, false, false, readInput, solve};\r\n    return run(argc, argv, task);\r\n}\r\n",
  "16": "// MPIBegin16. Сумма положительных чисел в главном процессе.\r\n#include \"console_mpi.hpp\"\r\nusing namespace console_mpi;\r\n\r\nRow readInput(int rank, int size, const Rows&) {\r\n    if (rank != 0) return numbers(label(rank) + \"одно целое число: \", 1, 1, true);\r\n    for (;;) {\r\n        Row row = numbers(\"Ранг 0 — сколько положительных чисел будет у остальных рангов? \", 1, 1, true);\r\n        int expected = std::stoi(row[0]);\r\n        if (expected >= 1 && expected < size) return row;\r\n        std::cout << \"Введите число от 1 до \" << size - 1 << \".\\n\";\r\n    }\r\n}\r\n\r\nbool consistent(const Rows& rows) {\r\n    int positive = 0;\r\n    for (size_t r = 1; r < rows.size(); ++r)\r\n        if (std::stoi(rows[r].at(0)) > 0) ++positive;\r\n    if (positive == std::stoi(rows[0].at(0))) return true;\r\n    std::cout << \"Число положительных значений не совпало с ожидаемым. Повторите опыт.\\n\";\r\n    return false;\r\n}\r\n\r\nvoid solve(int rank, int, const Row& row) {\r\n    MPI_Comm comm = MPI_COMM_WORLD;\r\n    int n = std::stoi(row.at(0));\r\n    if (rank == 0) {\r\n        long long sum = 0;\r\n        for (int i = 0; i < n; ++i) {\r\n            int value;\r\n            MPI_Status status;\r\n            MPI_Recv(&value, 1, MPI_INT, MPI_ANY_SOURCE, 0, comm, &status);\r\n            sum += value;\r\n        }\r\n        answer(0, std::to_string(sum));\r\n    } else if (n > 0) {\r\n        MPI_Send(&n, 1, MPI_INT, 0, 0, comm);\r\n    }\r\n}\r\n\r\nint main(int argc, char** argv) {\r\n    Task task = {\"MPIBegin16. Сумма положительных чисел в главном процессе.\", InputRanks::all, 2, false, false, readInput, solve, consistent};\r\n    return run(argc, argv, task);\r\n}\r\n",
  "18": "// MPIBegin18. Циклический сдвиг целых чисел на один ранг.\r\n#include \"console_mpi.hpp\"\r\nusing namespace console_mpi;\r\n\r\nRow readInput(int rank, int, const Rows&) {\r\n    return numbers(label(rank) + \"одно целое число: \", 1, 1, true);\r\n}\r\n\r\nvoid solve(int rank, int size, const Row& row) {\r\n    MPI_Comm comm = MPI_COMM_WORLD;\r\n    int value = std::stoi(row.at(0)), received;\r\n    int prev = (rank + size - 1) % size, next = (rank + 1) % size;\r\n    MPI_Status status;\r\n    if (size == 1) {\r\n        transferSelf(value, received, MPI_INT, rank, rank, status);\r\n    } else if (rank == 0) {\r\n        MPI_Send(&value, 1, MPI_INT, next, 0, comm);\r\n        MPI_Recv(&received, 1, MPI_INT, prev, 0, comm, &status);\r\n    } else {\r\n        MPI_Recv(&received, 1, MPI_INT, prev, 0, comm, &status);\r\n        MPI_Send(&value, 1, MPI_INT, next, 0, comm);\r\n    }\r\n    answer(rank, std::to_string(received));\r\n}\r\n\r\nint main(int argc, char** argv) {\r\n    Task task = {\"MPIBegin18. Циклический сдвиг целых чисел на один ранг.\", InputRanks::all, 1, false, true, readInput, solve};\r\n    return run(argc, argv, task);\r\n}\r\n",
  "21": "// MPIBegin21. Пересылка по перестановке адресатов.\r\n#include \"console_mpi.hpp\"\r\nusing namespace console_mpi;\r\n\r\nRow readInput(int rank, int size, const Rows& rows) {\r\n    return numbered(rank, rows, 0, size - 1, \"ранг получателя\");\r\n}\r\n\r\nvoid solve(int rank, int, const Row& row) {\r\n    MPI_Comm comm = MPI_COMM_WORLD;\r\n    double value = unpackReal(row.at(0)), received;\r\n    int dest = std::stoi(row.at(1));\r\n    MPI_Status status;\r\n    // Порядок локальных операций согласуется с убыванием ранга адресата.\r\n    if (dest == rank) {\r\n        transferSelf(value, received, MPI_DOUBLE, rank, MPI_ANY_SOURCE, status);\r\n    } else if (dest > rank) {\r\n        MPI_Send(&value, 1, MPI_DOUBLE, dest, 0, comm);\r\n        MPI_Recv(&received, 1, MPI_DOUBLE, MPI_ANY_SOURCE, 0, comm, &status);\r\n    } else {\r\n        MPI_Recv(&received, 1, MPI_DOUBLE, MPI_ANY_SOURCE, 0, comm, &status);\r\n        MPI_Send(&value, 1, MPI_DOUBLE, dest, 0, comm);\r\n    }\r\n    answer(rank, decimal(received) + \" (отправитель: \" + std::to_string(status.MPI_SOURCE) + \")\");\r\n}\r\n\r\nint main(int argc, char** argv) {\r\n    Task task = {\"MPIBegin21. Пересылка по перестановке адресатов.\", InputRanks::all, 1, false, true, readInput, solve};\r\n    return run(argc, argv, task);\r\n}\r\n",
  "24": "// MPIBegin24. Попарный обмен вещественными наборами.\r\n#include \"console_mpi.hpp\"\r\nusing namespace console_mpi;\r\n\r\nRow readInput(int rank, int, const Rows&) {\r\n    return numbers(label(rank) + \"введите от 1 до 4 чисел через пробел: \", 1, 4, false);\r\n}\r\n\r\nvoid solve(int rank, int, const Row& row) {\r\n    MPI_Comm comm = MPI_COMM_WORLD;\r\n    double outgoing[4], incoming[4];\r\n    int n = static_cast<int>(row.size());\r\n    if (n < 1 || n > 4) throw std::invalid_argument(\"N\");\r\n    for (int i = 0; i < n; ++i) outgoing[i] = unpackReal(row[i]);\r\n    int partner = (rank % 2 == 0) ? rank + 1 : rank - 1;\r\n    MPI_Status status;\r\n    MPI_Sendrecv(outgoing, n, MPI_DOUBLE, partner, 0, incoming, 4, MPI_DOUBLE,\r\n                 partner, 0, comm, &status);\r\n    int count;\r\n    MPI_Get_count(&status, MPI_DOUBLE, &count);\r\n    Row values;\r\n    for (int i = 0; i < count; ++i) values.push_back(decimal(incoming[i]));\r\n    answer(rank, join(values));\r\n}\r\n\r\nint main(int argc, char** argv) {\r\n    Task task = {\"MPIBegin24. Попарный обмен вещественными наборами.\", InputRanks::all, 2, true, false, readInput, solve};\r\n    return run(argc, argv, task);\r\n}\r\n",
  "26": "// MPIBegin26. Упорядочивание чисел по номерам в тегах сообщений.\r\n#include \"console_mpi.hpp\"\r\nusing namespace console_mpi;\r\n\r\nRow readInput(int rank, int size, const Rows& rows) {\r\n    return numbered(rank, rows, 1, size - 1, \"порядковый номер\");\r\n}\r\n\r\nvoid solve(int rank, int size, const Row& row) {\r\n    MPI_Comm comm = MPI_COMM_WORLD;\r\n    if (rank == 0) {\r\n        Row ordered;\r\n        for (int number = 1; number < size; ++number) {\r\n            double value;\r\n            MPI_Status status;\r\n            MPI_Recv(&value, 1, MPI_DOUBLE, MPI_ANY_SOURCE, number, comm, &status);\r\n            ordered.push_back(decimal(value));\r\n        }\r\n        answer(0, join(ordered));\r\n    } else {\r\n        double value = unpackReal(row.at(0));\r\n        int number = std::stoi(row.at(1));\r\n        MPI_Send(&value, 1, MPI_DOUBLE, 0, number, comm);\r\n    }\r\n}\r\n\r\nint main(int argc, char** argv) {\r\n    Task task = {\"MPIBegin26. Упорядочивание чисел по номерам в тегах сообщений.\", InputRanks::workers, 1, false, false, readInput, solve};\r\n    return run(argc, argv, task);\r\n}\r\n",
  "29": "// MPIBegin29. Наборы двух типов. Получение типа из тега сообщения.\r\n#include \"console_mpi.hpp\"\r\nusing namespace console_mpi;\r\n\r\nRow readInput(int rank, int, const Rows&) {\r\n    for (;;) {\r\n        Row row = readLine(label(rank) + \"тип (0 — целые, 1 — вещественные), затем до 10 чисел: \");\r\n        if (row.empty() || (row[0] != \"0\" && row[0] != \"1\")) {\r\n            std::cout << \"Ошибка: первое число — тип набора: 0 для целых, 1 для вещественных. Повторите строку.\\n\";\r\n            continue;\r\n        }\r\n        if (row.size() > 11) {\r\n            std::cout << \"Ошибка: после типа можно ввести не более 10 чисел. Повторите строку.\\n\";\r\n            continue;\r\n        }\r\n        const bool integers = row[0] == \"0\";\r\n        bool valid = true;\r\n        for (size_t i = 1; i < row.size(); ++i) {\r\n            if (!normalizeToken(row[i], integers)) {\r\n                std::cout << \"Ошибка: число №\" << i << \" в наборе должно быть \"\r\n                          << (integers ? \"целым (например, 2)\" : \"вещественным с точкой (например, 2.0)\")\r\n                          << \". Введено: \\\"\" << row[i] << \"\\\". Повторите строку.\\n\";\r\n                valid = false;\r\n                break;\r\n            }\r\n        }\r\n        if (valid) return row;\r\n    }\r\n}\r\n\r\nvoid solve(int rank, int size, const Row& row) {\r\n    MPI_Comm comm = MPI_COMM_WORLD;\r\n    if (rank > 0) {\r\n        int type = std::stoi(row.at(0));\r\n        int n = static_cast<int>(row.size()) - 1;\r\n        if (n > 10) throw std::invalid_argument(\"N\");\r\n        if (type == 0) {\r\n            int data[10]{};\r\n            for (int i = 0; i < n; ++i) data[i] = std::stoi(row[i + 1]);\r\n            MPI_Send(data, n, MPI_INT, 0, type, comm);\r\n        } else {\r\n            double data[10]{};\r\n            for (int i = 0; i < n; ++i) data[i] = unpackReal(row[i + 1]);\r\n            MPI_Send(data, n, MPI_DOUBLE, 0, type, comm);\r\n        }\r\n    } else {\r\n        Row values;\r\n        for (int source = 1; source < size; ++source) {\r\n            MPI_Status status;\r\n            MPI_Probe(source, MPI_ANY_TAG, comm, &status);\r\n            int tag = status.MPI_TAG, count;\r\n            if (tag == 0) {\r\n                int data[10]{};\r\n                MPI_Get_count(&status, MPI_INT, &count);\r\n                MPI_Recv(data, count, MPI_INT, source, tag, comm, &status);\r\n                for (int i = 0; i < count; ++i) values.push_back(std::to_string(data[i]));\r\n            } else {\r\n                double data[10]{};\r\n                MPI_Get_count(&status, MPI_DOUBLE, &count);\r\n                MPI_Recv(data, count, MPI_DOUBLE, source, tag, comm, &status);\r\n                for (int i = 0; i < count; ++i) values.push_back(decimal(data[i]));\r\n            }\r\n        }\r\n        answer(0, join(values));\r\n    }\r\n}\r\n\r\nint main(int argc, char** argv) {\r\n    Task task = {\"MPIBegin29. Наборы двух типов. Получение типа из тега сообщения.\", InputRanks::workers, 1, false, false, readInput, solve};\r\n    return run(argc, argv, task);\r\n}\r\n",
  "30": "#include \"console_mpi.hpp\"\nusing namespace console_mpi;\n\nRow readInput(int, int, const Rows&) {\n    return numbers(\"Ранг 0 — одно целое число: \", 1, 1, true);\n}\n\nvoid solve(int rank, int, const Row& row) {\n    int value = rank == 0 ? valuesOf<int>(row).at(0) : 0;\n    MPI_Bcast(&value, 1, MPI_INT, 0, MPI_COMM_WORLD);\n    if (rank != 0) answer(rank, std::to_string(value));\n}\n\nint main(int argc, char** argv) {\n    Task task = {\"MPIBegin30. MPI_Bcast: число от ранга 0 всем остальным.\",\n                 InputRanks::root, 2, false, false, readInput, solve};\n    return run(argc, argv, task);\n}\n",
  "34": "#include \"console_mpi.hpp\"\nusing namespace console_mpi;\n\nRow readInput(int rank, int, const Rows&) {\n    const size_t count = rank + 2;\n    return numbers(label(rank) + std::to_string(count) + \" целых чисел: \", count, count, true);\n}\n\nvoid solve(int rank, int size, const Row& row) {\n    std::vector<int> send = valuesOf<int>(row);\n    std::vector<int> counts(size), offsets(size);\n    for (int r = 0, offset = 0; r < size; ++r) {\n        counts[r] = r + 2;\n        offsets[r] = offset;\n        offset += counts[r];\n    }\n    std::vector<int> received(rank == 0 ? offsets.back() + counts.back() : 0);\n    MPI_Gatherv(send.data(), static_cast<int>(send.size()), MPI_INT,\n                received.data(), counts.data(), offsets.data(), MPI_INT, 0, MPI_COMM_WORLD);\n    if (rank == 0) printValues(rank, received);\n}\n\nint main(int argc, char** argv) {\n    Task task = {\"MPIBegin34. MPI_Gatherv: наборы длиной ранг + 2 в главный процесс.\",\n                 InputRanks::all, 2, false, false, readInput, solve};\n    return run(argc, argv, task);\n}\n",
  "37": "#include \"console_mpi.hpp\"\nusing namespace console_mpi;\n\nRow readInput(int, int size, const Rows&) {\n    return numbers(\"Ранг 0 — \" + std::to_string(size) + \" вещественных чисел: \",\n                   size, size, false);\n}\n\nvoid solve(int rank, int size, const Row& row) {\n    std::vector<double> send = rank == 0 ? valuesOf<double>(row) : std::vector<double>{};\n    std::vector<int> counts(size, 1), offsets(size);\n    for (int r = 0; r < size; ++r) offsets[r] = size - 1 - r;\n    double received = 0;\n    MPI_Scatterv(send.data(), counts.data(), offsets.data(), MPI_DOUBLE,\n                 &received, 1, MPI_DOUBLE, 0, MPI_COMM_WORLD);\n    answer(rank, decimal(received));\n}\n\nint main(int argc, char** argv) {\n    Task task = {\"MPIBegin37. MPI_Scatterv: числа в обратном порядке рангов.\",\n                 InputRanks::root, 2, false, false, readInput, solve};\n    return run(argc, argv, task);\n}\n",
  "40": "#include \"console_mpi.hpp\"\nusing namespace console_mpi;\n\nRow readInput(int rank, int, const Rows&) {\n    return numbers(label(rank) + \"одно вещественное число: \", 1, 1, false);\n}\n\nvoid solve(int rank, int size, const Row& row) {\n    double send = valuesOf<double>(row).at(0);\n    std::vector<double> received(size);\n    MPI_Allgather(&send, 1, MPI_DOUBLE, received.data(), 1, MPI_DOUBLE, MPI_COMM_WORLD);\n    printValues(rank, received);\n}\n\nint main(int argc, char** argv) {\n    Task task = {\"MPIBegin40. MPI_Allgather: число каждого процесса всем процессам.\",\n                 InputRanks::all, 2, false, false, readInput, solve};\n    return run(argc, argv, task);\n}\n",
  "43": "#include \"console_mpi.hpp\"\nusing namespace console_mpi;\n\nRow readInput(int rank, int size, const Rows&) {\n    return numbers(label(rank) + std::to_string(size) + \" вещественных чисел, по одному каждому рангу: \",\n                   size, size, false);\n}\n\nvoid solve(int rank, int size, const Row& row) {\n    std::vector<double> send = valuesOf<double>(row), received(size);\n    MPI_Alltoall(send.data(), 1, MPI_DOUBLE, received.data(), 1, MPI_DOUBLE, MPI_COMM_WORLD);\n    printValues(rank, received);\n}\n\nint main(int argc, char** argv) {\n    Task task = {\"MPIBegin43. MPI_Alltoall: по одному числу от каждого источника.\",\n                 InputRanks::all, 2, false, false, readInput, solve};\n    return run(argc, argv, task);\n}\n",
  "45": "#include \"console_mpi.hpp\"\nusing namespace console_mpi;\n\nRow readInput(int rank, int size, const Rows&) {\n    const size_t count = size * (size + 1) / 2;\n    return numbers(label(rank) + std::to_string(count) + \" целых чисел; блоки для рангов 0, 1, ... имеют длины 1, 2, ...: \",\n                   count, count, true);\n}\n\nvoid solve(int rank, int size, const Row& row) {\n    std::vector<int> send = valuesOf<int>(row);\n    std::vector<int> sendCounts(size), sendOffsets(size), recvCounts(size, rank + 1), recvOffsets(size);\n    for (int r = 0, offset = 0; r < size; ++r) {\n        sendCounts[r] = r + 1;\n        sendOffsets[r] = offset;\n        offset += sendCounts[r];\n        recvOffsets[r] = r * (rank + 1);\n    }\n    std::vector<int> received(size * (rank + 1));\n    MPI_Alltoallv(send.data(), sendCounts.data(), sendOffsets.data(), MPI_INT,\n                  received.data(), recvCounts.data(), recvOffsets.data(), MPI_INT,\n                  MPI_COMM_WORLD);\n    printValues(rank, received);\n}\n\nint main(int argc, char** argv) {\n    Task task = {\"MPIBegin45. MPI_Alltoallv: в ранг R по R + 1 чисел от каждого.\",\n                 InputRanks::all, 2, false, false, readInput, solve};\n    return run(argc, argv, task);\n}\n",
  "48": "// MPIBegin48. Суммы элементов с одинаковыми номерами.\n#include \"console_mpi.hpp\"\nusing namespace console_mpi;\n\nRow readInput(int rank, int size, const Rows&) {\n    int count = size + 5;\n    return numbers(label(rank) + \"введите чисел: \" + std::to_string(count) + \" (целые, через пробел): \", count, count, true);\n}\n\nvoid solve(int rank, int size, const Row& row) {\n    auto local = valuesOf<int>(row);\n    std::vector<int> result(size + 5);\n    MPI_Reduce(local.data(), result.data(), size + 5, MPI_INT, MPI_SUM, 0, MPI_COMM_WORLD);\n    if (rank == 0) printValues(rank, result);\n}\n\nint main(int argc, char** argv) {\n    Task task = {\"MPIBegin48. Суммы элементов с одинаковыми номерами.\", InputRanks::all, 1, false, false, readInput, solve};\n    return run(argc, argv, task);\n}\r\n",
  "51": "// MPIBegin51. Произведения элементов с одинаковыми номерами.\n#include \"console_mpi.hpp\"\nusing namespace console_mpi;\n\nRow readInput(int rank, int size, const Rows&) {\n    int count = size + 5;\n    return numbers(label(rank) + \"введите чисел: \" + std::to_string(count) + \" (вещественные, через пробел): \", count, count, false);\n}\n\nvoid solve(int rank, int size, const Row& row) {\n    auto local = valuesOf<double>(row);\n    std::vector<double> result(size + 5);\n    MPI_Allreduce(local.data(), result.data(), size + 5, MPI_DOUBLE, MPI_PROD, MPI_COMM_WORLD);\n    printValues(rank, result);\n}\n\nint main(int argc, char** argv) {\n    Task task = {\"MPIBegin51. Произведения элементов с одинаковыми номерами.\", InputRanks::all, 1, false, false, readInput, solve};\n    return run(argc, argv, task);\n}\r\n",
  "54": "// MPIBegin54. Два максимума для каждого ранга.\n#include \"console_mpi.hpp\"\nusing namespace console_mpi;\n\nRow readInput(int rank, int size, const Rows&) {\n    int count = 2 * size;\n    return numbers(label(rank) + \"введите чисел: \" + std::to_string(count) + \" (вещественные, через пробел): \", count, count, false);\n}\n\nvoid solve(int rank, int size, const Row& row) {\n    auto local = valuesOf<double>(row);\n    std::vector<double> result(2);\n    std::vector<int> counts(size, 2);\n    MPI_Reduce_scatter(local.data(), result.data(), counts.data(), MPI_DOUBLE, MPI_MAX, MPI_COMM_WORLD);\n    printValues(rank, result);\n}\n\nint main(int argc, char** argv) {\n    Task task = {\"MPIBegin54. Два максимума для каждого ранга.\", InputRanks::all, 1, false, false, readInput, solve};\n    return run(argc, argv, task);\n}\r\n",
  "57": "// MPIBegin57. Максимумы от ранга 0 до текущего ранга.\n#include \"console_mpi.hpp\"\nusing namespace console_mpi;\n\nRow readInput(int rank, int size, const Rows&) {\n    int count = size + 5;\n    return numbers(label(rank) + \"введите чисел: \" + std::to_string(count) + \" (целые, через пробел): \", count, count, true);\n}\n\nvoid solve(int rank, int size, const Row& row) {\n    auto local = valuesOf<int>(row);\n    std::vector<int> result(size + 5);\n    MPI_Scan(local.data(), result.data(), size + 5, MPI_INT, MPI_MAX, MPI_COMM_WORLD);\n    printValues(rank, result);\n}\n\nint main(int argc, char** argv) {\n    Task task = {\"MPIBegin57. Максимумы от ранга 0 до текущего ранга.\", InputRanks::all, 1, false, false, readInput, solve};\n    return run(argc, argv, task);\n}\r\n",
  "59": "// MPIBegin59. По одной тройке целых чисел каждому подчинённому процессу.\n#include \"console_mpi.hpp\"\nusing namespace console_mpi;\n\nRow readInput(int rank, int size, const Rows&) {\n    int count = 3 * (size - 1);\n    return numbers(label(rank) + \"введите \" + std::to_string(count) + \" целых чисел, по тройке для рангов от 1 до \" + std::to_string(size - 1) + \": \", count, count, true);\n}\n\nvoid solve(int rank, int size, const Row& row) {\n    MPI_Datatype triple;\n    MPI_Type_contiguous(3, MPI_INT, &triple);\n    MPI_Type_commit(&triple);\n    std::vector<int> source(3 * size), local(3);\n    if (rank == 0) {\n        auto values = valuesOf<int>(row);\n        std::copy(values.begin(), values.end(), source.begin() + 3);\n    }\n    MPI_Scatter(source.data(), 1, triple, local.data(), 1, triple, 0, MPI_COMM_WORLD);\n    MPI_Type_free(&triple);\n    if (rank != 0) printValues(rank, local);\n}\n\nint main(int argc, char** argv) {\n    Task task = {\"MPIBegin59. По одной тройке целых чисел каждому подчинённому процессу.\", InputRanks::root, 2, false, false, readInput, solve};\n    return run(argc, argv, task);\n}\r\n",
  "62": "// MPIBegin62. Рассылка троек составного типа.\n#include \"console_mpi.hpp\"\nusing namespace console_mpi;\n\nRow readInput(int rank, int size, const Rows&) {\n    return mixedTriples(rank, size - 1, 1, \"вещественное\");\n}\n\nstruct Record { int first, last; double real; };\n\nRecord readRecord(const Row& row, int start) {\n    return {std::stoi(row.at(start)), std::stoi(row.at(start + 2)), std::stod(row.at(start + 1))};\n}\n\nstd::string showRecord(const Record& record) {\n    return std::to_string(record.first) + \" \" + decimal(record.real) + \" \" + std::to_string(record.last);\n}\n\nvoid solve(int rank, int size, const Row& row) {\n    int lengths[] = {2, 1};\n    MPI_Aint offsets[] = {offsetof(Record, first), offsetof(Record, real)};\n    MPI_Datatype fields[] = {MPI_INT, MPI_DOUBLE}, triple;\n    MPI_Type_create_struct(2, lengths, offsets, fields, &triple);\n    MPI_Type_commit(&triple);\n    std::vector<Record> records(size);\n    Record local{};\n    if (rank == 0)\n        for (int r = 1; r < size; ++r) records[r] = readRecord(row, 3 * (r - 1));\n    MPI_Scatter(records.data(), 1, triple, &local, 1, triple, 0, MPI_COMM_WORLD);\n    if (rank != 0) answer(rank, showRecord(local));\n    MPI_Type_free(&triple);\n}\n\nint main(int argc, char** argv) {\n    Task task = {\"MPIBegin62. Рассылка троек составного типа.\", InputRanks::root, 2, false, false, readInput, solve};\n    return run(argc, argv, task);\n}\r\n",
  "64": "// MPIBegin64. Сбор троек составного типа во всех процессах.\n#include \"console_mpi.hpp\"\nusing namespace console_mpi;\n\nRow readInput(int rank, int, const Rows&) {\n    return mixedTriples(rank, 1, 1, \"вещественное\");\n}\n\nstruct Record { int first, last; double real; };\n\nRecord readRecord(const Row& row, int start) {\n    return {std::stoi(row.at(start)), std::stoi(row.at(start + 2)), std::stod(row.at(start + 1))};\n}\n\nstd::string showRecord(const Record& record) {\n    return std::to_string(record.first) + \" \" + decimal(record.real) + \" \" + std::to_string(record.last);\n}\n\nvoid solve(int rank, int size, const Row& row) {\n    int lengths[] = {2, 1};\n    MPI_Aint offsets[] = {offsetof(Record, first), offsetof(Record, real)};\n    MPI_Datatype fields[] = {MPI_INT, MPI_DOUBLE}, triple;\n    MPI_Type_create_struct(2, lengths, offsets, fields, &triple);\n    MPI_Type_commit(&triple);\n    std::vector<Record> records(size);\n    Record local = readRecord(row, 0);\n    MPI_Allgather(&local, 1, triple, records.data(), 1, triple, MPI_COMM_WORLD);\n    Row result;\n    for (const auto& record : records) result.push_back(showRecord(record));\n    answer(rank, join(result));\n    MPI_Type_free(&triple);\n}\n\nint main(int argc, char** argv) {\n    Task task = {\"MPIBegin64. Сбор троек составного типа во всех процессах.\", InputRanks::all, 1, false, false, readInput, solve};\n    return run(argc, argv, task);\n}\r\n",
  "67": "// MPIBegin67. Упаковка и рассылка троек.\n#include \"console_mpi.hpp\"\n#include <cctype>\n#include <cmath>\n#include <iostream>\n#include <sstream>\n#include <string>\n#include <vector>\n\nusing namespace console_mpi;\n\nbool isStrictInt(const std::string& token) {\n    if (token.empty()) return false;\n    std::size_t i = (token[0] == '+' || token[0] == '-') ? 1 : 0;\n    if (i == token.size()) return false;\n    for (; i < token.size(); ++i) {\n        if (!std::isdigit(static_cast<unsigned char>(token[i]))) return false;\n    }\n    try {\n        std::size_t pos = 0;\n        (void)std::stoi(token, &pos);\n        return pos == token.size();\n    } catch (...) {\n        return false;\n    }\n}\n\nbool isStrictReal(const std::string& token) {\n    if (token.empty()) return false;\n    std::size_t i = (token[0] == '+' || token[0] == '-') ? 1 : 0;\n    std::size_t dotPos = token.find('.', i);\n    // Обязательно должна быть точка и цифры по обе стороны от неё (целые вроде \"5\" не пройдут)\n    if (dotPos == std::string::npos || dotPos == i || dotPos + 1 == token.size()) return false;\n    for (std::size_t j = i; j < token.size(); ++j) {\n        if (j == dotPos) continue;\n        if (!std::isdigit(static_cast<unsigned char>(token[j]))) return false;\n    }\n    try {\n        std::size_t pos = 0;\n        double value = std::stod(token, &pos);\n        return pos == token.size() && std::isfinite(value);\n    } catch (...) {\n        return false;\n    }\n}\n\nRow readInput(int rank, int size, const Rows&) {\n    int triples = size - 1;\n    int total = triples * 3;\n\n    while (true) {\n        Row row = readLine(label(rank) + \"троек: \" + std::to_string(triples)\n            + \", порядок: целое, вещественное, целое, всего чисел: \" + std::to_string(total) + \": \");\n        if (row.empty()) continue;\n\n        if (static_cast<int>(row.size()) != total) {\n            std::cout << \"Ошибка: нужно ввести ровно \" << total\n                      << \" чисел (введено \" << row.size() << \"). Повторите ввод.\\n\";\n            continue;\n        }\n\n        bool ok = true;\n        for (int t = 0; t < triples; ++t) {\n            int base = t * 3;\n\n            if (!isStrictInt(row[base + 0])) {\n                std::cout << \"Ошибка: в тройке \" << (t + 1)\n                          << \" на 1-й позиции ожидается ЦЕЛОЕ число, а введено \\\"\"\n                          << row[base + 0] << \"\\\". Повторите ввод.\\n\";\n                ok = false;\n                break;\n            }\n\n            if (!isStrictReal(row[base + 1])) {\n                std::cout << \"Ошибка: в тройке \" << (t + 1)\n                          << \" на 2-й позиции ожидается ВЕЩЕСТВЕННОЕ число с точкой (например, 4.2), а введено \\\"\"\n                          << row[base + 1] << \"\\\". Повторите ввод.\\n\";\n                ok = false;\n                break;\n            }\n\n            if (!isStrictInt(row[base + 2])) {\n                std::cout << \"Ошибка: в тройке \" << (t + 1)\n                          << \" на 3-й позиции ожидается ЦЕЛОЕ число, а введено \\\"\"\n                          << row[base + 2] << \"\\\". Повторите ввод.\\n\";\n                ok = false;\n                break;\n            }\n        }\n\n        if (ok) return row;\n    }\n}\n\nvoid packTriple(const Row& row, int start, char* packet, int capacity) {\n    int position = 0;\n    int first = std::stoi(row.at(start + 0));\n    MPI_Pack(&first, 1, MPI_INT, packet, capacity, &position, MPI_COMM_WORLD);\n    double real = std::stod(row.at(start + 1));\n    MPI_Pack(&real, 1, MPI_DOUBLE, packet, capacity, &position, MPI_COMM_WORLD);\n    int second = std::stoi(row.at(start + 2));\n    MPI_Pack(&second, 1, MPI_INT, packet, capacity, &position, MPI_COMM_WORLD);\n}\n\nstd::string unpackTriple(char* packet, int capacity) {\n    int position = 0;\n    int first = 0, second = 0;\n    double real = 0.0;\n    MPI_Unpack(packet, capacity, &position, &first, 1, MPI_INT, MPI_COMM_WORLD);\n    MPI_Unpack(packet, capacity, &position, &real, 1, MPI_DOUBLE, MPI_COMM_WORLD);\n    MPI_Unpack(packet, capacity, &position, &second, 1, MPI_INT, MPI_COMM_WORLD);\n    return std::to_string(first) + \" \" + decimal(real) + \" \" + std::to_string(second);\n}\n\nvoid solve(int rank, int size, const Row& row) {\n    int intBytes = 0, realBytes = 0;\n    MPI_Pack_size(1, MPI_INT, MPI_COMM_WORLD, &intBytes);\n    MPI_Pack_size(1, MPI_DOUBLE, MPI_COMM_WORLD, &realBytes);\n    int width = 2 * intBytes + realBytes;\n\n    std::vector<char> packets(size * width, 0);\n    std::vector<char> local(width, 0);\n\n    if (rank == 0) {\n        for (int r = 1; r < size; ++r) {\n            packTriple(row, (r - 1) * 3, packets.data() + r * width, width);\n        }\n    }\n\n    MPI_Scatter(packets.data(), width, MPI_PACKED,\n                local.data(), width, MPI_PACKED,\n                0, MPI_COMM_WORLD);\n\n    if (rank != 0) answer(rank, unpackTriple(local.data(), width));\n}\n\nint main(int argc, char** argv) {\n    Task task = {\"MPIBegin67. Упаковка и рассылка троек.\", InputRanks::root, 2, false, false, readInput, solve};\n    return run(argc, argv, task);\n}\n",
  "69": "// MPIBegin69. Сбор упакованных троек в главном процессе.\n#include \"console_mpi.hpp\"\nusing namespace console_mpi;\n\nRow readInput(int rank, int, const Rows&) {\n    return mixedTriples(rank, 1, 2,\"вещественное\");\n}\n\nvoid packTriple(const Row& row, int start, char* packet, int capacity) {\n    int position = 0;\n    int first = std::stoi(row.at(start + 0));\n    MPI_Pack(&first, 1, MPI_INT, packet, capacity, &position, MPI_COMM_WORLD);\n    int second = std::stoi(row.at(start + 1));\n    MPI_Pack(&second, 1, MPI_INT, packet, capacity, &position, MPI_COMM_WORLD);\n    double real = std::stod(row.at(start + 2));\n    MPI_Pack(&real, 1, MPI_DOUBLE, packet, capacity, &position, MPI_COMM_WORLD);\n}\n\nstd::string unpackTriple(char* packet, int capacity) {\n    int position = 0;\n    int first, second;\n    double real;\n    MPI_Unpack(packet, capacity, &position, &first, 1, MPI_INT, MPI_COMM_WORLD);\n    MPI_Unpack(packet, capacity, &position, &second, 1, MPI_INT, MPI_COMM_WORLD);\n    MPI_Unpack(packet, capacity, &position, &real, 1, MPI_DOUBLE, MPI_COMM_WORLD);\n    return std::to_string(first) + \" \" + std::to_string(second) + \" \" + decimal(real);\n}\n\nvoid solve(int rank, int size, const Row& row) {\n    int intBytes, realBytes;\n    MPI_Pack_size(1, MPI_INT, MPI_COMM_WORLD, &intBytes);\n    MPI_Pack_size(1, MPI_DOUBLE, MPI_COMM_WORLD, &realBytes);\n    int width = 2 * intBytes + realBytes;\n    std::vector<char> packets(size * width), local(width);\n    if (rank != 0) packTriple(row, 0, local.data(), width);\n    MPI_Gather(local.data(), width, MPI_BYTE, packets.data(), width, MPI_BYTE, 0, MPI_COMM_WORLD);\n    if (rank == 0) {\n        Row result;\n        for (int r = 1; r < size; ++r) result.push_back(unpackTriple(packets.data() + r * width, width));\n        answer(rank, join(result));\n    }\n}\n\nint main(int argc, char** argv) {\n    Task task = {\"MPIBegin69. Сбор упакованных троек в главном процессе.\", InputRanks::workers, 2, false, false, readInput, solve};\n    return run(argc, argv, task);\n}\n",
  "71": "#include \"console_mpi.hpp\"\nusing namespace console_mpi;\n\nRow readInput(int, int size, const Rows&) {\n    const size_t count = (size + 1) / 2;\n    return numbers(\"Ранг 0 — \" + std::to_string(count) + \" целых чисел для рангов 0, 2, 4, ...: \",\n                   count, count, true);\n}\n\nvoid solve(int rank, int size, const Row& row) {\n    std::vector<int> evenRanks;\n    for (int r = 0; r < size; r += 2) evenRanks.push_back(r);\n    MPI_Group worldGroup, evenGroup;\n    MPI_Comm_group(MPI_COMM_WORLD, &worldGroup);\n    MPI_Group_incl(worldGroup, static_cast<int>(evenRanks.size()), evenRanks.data(), &evenGroup);\n    MPI_Comm evenComm;\n    MPI_Comm_create(MPI_COMM_WORLD, evenGroup, &evenComm);\n    if (evenComm != MPI_COMM_NULL) {\n        std::vector<int> send = rank == 0 ? valuesOf<int>(row) : std::vector<int>{};\n        int received = 0;\n        MPI_Scatter(send.data(), 1, MPI_INT, &received, 1, MPI_INT, 0, evenComm);\n        answer(rank, std::to_string(received));\n        MPI_Comm_free(&evenComm);\n    }\n    MPI_Group_free(&evenGroup);\n    MPI_Group_free(&worldGroup);\n}\n\nint main(int argc, char** argv) {\n    Task task = {\"MPIBegin71. Коммуникатор чётных рангов: рассылка чисел.\",\n                 InputRanks::root, 2, false, false, readInput, solve};\n    return run(argc, argv, task);\n}\n",
  "75": "#include \"console_mpi.hpp\"\nusing namespace console_mpi;\n\nRow readInput(int rank, int, const Rows&) {\n    return numbers(label(rank) + \"одно вещественное число: \", 1, 1, false);\n}\n\nvoid solve(int rank, int, const Row& row) {\n    MPI_Comm subgroup;\n    MPI_Comm_split(MPI_COMM_WORLD, rank % 2, rank, &subgroup);\n    double value = valuesOf<double>(row).at(0), result = 0;\n    MPI_Reduce(&value, &result, 1, MPI_DOUBLE,\n               rank % 2 == 0 ? MPI_MAX : MPI_MIN, 0, subgroup);\n    if (rank == 0 || rank == 1) answer(rank, decimal(result));\n    MPI_Comm_free(&subgroup);\n}\n\nint main(int argc, char** argv) {\n    Task task = {\"MPIBegin75. Максимум чётных и минимум нечётных рангов.\",\n                 InputRanks::all, 2, false, false, readInput, solve};\n    return run(argc, argv, task);\n}\n",
  "77": "#include \"console_mpi.hpp\"\nusing namespace console_mpi;\n\nRow readInput(int rank, int, const Rows&) {\n    for (;;) {\n        Row row = readLine(label(rank) + \"N (0 или 1); при N=1 добавьте вещественное A: \");\n        if (row.empty() || (row[0] != \"0\" && row[0] != \"1\")) {\n            std::cout << \"Ошибка: первое число N должно быть целым 0 или 1. Повторите строку.\\n\";\n            continue;\n        }\n        const size_t expected = row[0] == \"1\" ? 2 : 1;\n        if (row.size() != expected) {\n            std::cout << \"Ошибка: при N=\" << row[0] << \" ожидается \" << expected\n                      << \" чисел. Повторите строку.\\n\";\n            continue;\n        }\n        if (expected == 2) {\n            double value;\n            if (!strictReal(row[1], value)) {\n                std::cout << \"Ошибка: число A должно быть вещественным с точкой (например, 2.0). Повторите строку.\\n\";\n                continue;\n            }\n            row[1] = decimal(value);\n        }\n        return row;\n    }\n}\n\nbool valid(const Rows& rows) {\n    for (const Row& row : rows) if (row.at(0) == \"1\") return true;\n    std::cout << \"Ошибка: нужен хотя бы один ранг с N=1. Начните ввод заново с числа процессов.\\n\";\n    return false;\n}\n\nvoid solve(int rank, int, const Row& row) {\n    const bool included = row.at(0) == \"1\";\n    MPI_Comm subgroup;\n    MPI_Comm_split(MPI_COMM_WORLD, included ? 1 : MPI_UNDEFINED, rank, &subgroup);\n    if (included) {\n        int count;\n        MPI_Comm_size(subgroup, &count);\n        double value = unpackReal(row.at(1));\n        std::vector<double> received(count);\n        MPI_Gather(&value, 1, MPI_DOUBLE, received.data(), 1, MPI_DOUBLE, 0, subgroup);\n        int localRank;\n        MPI_Comm_rank(subgroup, &localRank);\n        if (localRank == 0) printValues(rank, received);\n        MPI_Comm_free(&subgroup);\n    }\n}\n\nint main(int argc, char** argv) {\n    Task task = {\"MPIBegin77. Числа рангов с N=1 первому из этих рангов.\",\n                 InputRanks::all, 2, false, false, readInput, solve, valid};\n    return run(argc, argv, task);\n}\n",
  "79": "#include \"console_mpi.hpp\"\nusing namespace console_mpi;\n\nRow readInput(int rank, int, const Rows&) {\n    for (;;) {\n        Row row = readLine(label(rank) + \"N (0 или 1); при N=1 добавьте вещественное A: \");\n        if (row.empty() || (row[0] != \"0\" && row[0] != \"1\")) {\n            std::cout << \"Ошибка: первое число N должно быть целым 0 или 1. Повторите строку.\\n\";\n            continue;\n        }\n        const size_t expected = row[0] == \"1\" ? 2 : 1;\n        if (row.size() != expected) {\n            std::cout << \"Ошибка: при N=\" << row[0] << \" ожидается \" << expected\n                      << \" чисел. Повторите строку.\\n\";\n            continue;\n        }\n        if (expected == 2) {\n            double value;\n            if (!strictReal(row[1], value)) {\n                std::cout << \"Ошибка: число A должно быть вещественным с точкой (например, 2.0). Повторите строку.\\n\";\n                continue;\n            }\n            row[1] = decimal(value);\n        }\n        return row;\n    }\n}\n\nbool valid(const Rows& rows) {\n    for (const Row& row : rows) if (row.at(0) == \"1\") return true;\n    std::cout << \"Ошибка: нужен хотя бы один ранг с N=1. Начните ввод заново с числа процессов.\\n\";\n    return false;\n}\n\nvoid solve(int rank, int, const Row& row) {\n    const bool included = row.at(0) == \"1\";\n    MPI_Comm subgroup;\n    MPI_Comm_split(MPI_COMM_WORLD, included ? 1 : MPI_UNDEFINED, rank, &subgroup);\n    if (included) {\n        int count;\n        MPI_Comm_size(subgroup, &count);\n        double value = unpackReal(row.at(1));\n        std::vector<double> received(count);\n        MPI_Allgather(&value, 1, MPI_DOUBLE, received.data(), 1, MPI_DOUBLE, subgroup);\n        printValues(rank, received);\n        MPI_Comm_free(&subgroup);\n    }\n}\n\nint main(int argc, char** argv) {\n    Task task = {\"MPIBegin79. Числа рангов с N=1 всем рангам с N=1.\",\n                 InputRanks::all, 2, false, false, readInput, solve, valid};\n    return run(argc, argv, task);\n}\n",
  "80": "#include \"console_mpi.hpp\"\nusing namespace console_mpi;\n\nRow readInput(int rank, int, const Rows&) {\n    for (;;) {\n        Row row = numbers(label(rank) + \"N (1 или 2) и целое A: \", 2, 2, true);\n        if (row[0] == \"1\" || row[0] == \"2\") return row;\n        std::cout << \"Ошибка: первое число N должно быть 1 или 2. Повторите строку.\\n\";\n    }\n}\n\nbool valid(const Rows& rows) {\n    bool one = false, two = false;\n    for (const Row& row : rows) {\n        one |= row.at(0) == \"1\";\n        two |= row.at(0) == \"2\";\n    }\n    if (one && two) return true;\n    std::cout << \"Ошибка: нужны процессы с N=1 и с N=2. Начните ввод заново с числа процессов.\\n\";\n    return false;\n}\n\nvoid solve(int rank, int, const Row& row) {\n    MPI_Comm subgroup;\n    MPI_Comm_split(MPI_COMM_WORLD, std::stoi(row.at(0)), rank, &subgroup);\n    int count;\n    MPI_Comm_size(subgroup, &count);\n    int value = valuesOf<int>(Row{row.at(1)}).at(0);\n    std::vector<int> received(count);\n    MPI_Allgather(&value, 1, MPI_INT, received.data(), 1, MPI_INT, subgroup);\n    printValues(rank, received);\n    MPI_Comm_free(&subgroup);\n}\n\nint main(int argc, char** argv) {\n    Task task = {\"MPIBegin80. Числа каждой группы N=1 или N=2 всем внутри группы.\",\n                 InputRanks::all, 2, false, false, readInput, solve, valid};\n    return run(argc, argv, task);\n}\n",
  "83": "#include \"console_mpi.hpp\"\nusing namespace console_mpi;\n\nRow readInput(int, int size, const Rows&) {\n    for (;;) {\n        Row row = numbers(\"Ранг 0 — целое N (>1), делящее K=\" + std::to_string(size) + \": \", 1, 1, true);\n        const int n = std::stoi(row[0]);\n        if (n > 1 && size % n == 0) return row;\n        std::cout << \"Ошибка: N должно быть больше 1 и делить K без остатка. Повторите строку.\\n\";\n    }\n}\n\nvoid solve(int rank, int size, const Row& row) {\n    int n = rank == 0 ? std::stoi(row.at(0)) : 0;\n    MPI_Bcast(&n, 1, MPI_INT, 0, MPI_COMM_WORLD);\n    int dims[2] = {n, size / n}, periods[2] = {0, 0};\n    MPI_Comm cart;\n    MPI_Cart_create(MPI_COMM_WORLD, 2, dims, periods, 0, &cart);\n    int cartRank, coords[2];\n    MPI_Comm_rank(cart, &cartRank);\n    MPI_Cart_coords(cart, cartRank, 2, coords);\n    answer(rank, std::to_string(coords[0]) + \" \" + std::to_string(coords[1]));\n    MPI_Comm_free(&cart);\n}\n\nint main(int argc, char** argv) {\n    Task task = {\"MPIBegin83. Координаты матрицы N × K/N.\",\n                 InputRanks::root, 2, false, false, readInput, solve};\n    return run(argc, argv, task);\n}\n",
  "85": "#include \"console_mpi.hpp\"\nusing namespace console_mpi;\n\nRow readInput(int rank, int size, const Rows&) {\n    if (rank != 0 && rank != size / 2) return {};\n    return numbers(label(rank) + \"вещественное A для своей строки: \", 1, 1, false);\n}\n\nbool validSize(int size) { return size >= 4 && size % 2 == 0; }\n\nvoid solve(int rank, int size, const Row& row) {\n    int dims[2] = {2, size / 2}, periods[2] = {0, 0};\n    MPI_Comm cart, line;\n    MPI_Cart_create(MPI_COMM_WORLD, 2, dims, periods, 0, &cart);\n    int remain[2] = {0, 1};\n    MPI_Cart_sub(cart, remain, &line);\n    double value = (rank == 0 || rank == size / 2) ? valuesOf<double>(row).at(0) : 0;\n    MPI_Bcast(&value, 1, MPI_DOUBLE, 0, line);\n    answer(rank, decimal(value));\n    MPI_Comm_free(&line);\n    MPI_Comm_free(&cart);\n}\n\nint main(int argc, char** argv) {\n    Task task = {\"MPIBegin85. Две строки топологии: рассылка A внутри каждой.\",\n                 InputRanks::all, 4, false, false, readInput, solve, nullptr, validSize};\n    return run(argc, argv, task);\n}\n",
  "92": "#include \"console_mpi.hpp\"\nusing namespace console_mpi;\n\nRow readInput(int rank, int, const Rows&) {\n    return numbers(label(rank) + \"одно вещественное число: \", 1, 1, false);\n}\n\nbool validSize(int size) { return size == 8 || size == 12; }\n\nvoid solve(int rank, int size, const Row& row) {\n    int dims[3] = {2, 2, size / 4}, periods[3] = {0, 0, 0};\n    MPI_Comm cart, square;\n    MPI_Cart_create(MPI_COMM_WORLD, 3, dims, periods, 0, &cart);\n    int remain[3] = {1, 1, 0};\n    MPI_Cart_sub(cart, remain, &square);\n    double value = valuesOf<double>(row).at(0), sum = 0;\n    MPI_Allreduce(&value, &sum, 1, MPI_DOUBLE, MPI_SUM, square);\n    answer(rank, decimal(sum));\n    MPI_Comm_free(&square);\n    MPI_Comm_free(&cart);\n}\n\nint main(int argc, char** argv) {\n    Task task = {\"MPIBegin92. Сумма в каждой матрице 2 × 2 трёхмерной решётки.\",\n                 InputRanks::all, 8, false, false, readInput, solve, nullptr, validSize};\n    return run(argc, argv, task);\n}\n",
  "94": "#include \"console_mpi.hpp\"\nusing namespace console_mpi;\n\nRow readInput(int rank, int size, const Rows& rows) {\n    if (rank == 0) {\n        for (;;) {\n            Row dimensions = numbers(\"Ранг 0 — положительные целые M и N (M·N ≤ K): \", 2, 2, true);\n            const int m = std::stoi(dimensions[0]), n = std::stoi(dimensions[1]);\n            if (m > 0 && n > 0 && m <= size / n) {\n                Row coords = numbers(\"Ранг 0 — целые координаты X и Y: \", 2, 2, true);\n                dimensions.insert(dimensions.end(), coords.begin(), coords.end());\n                return dimensions;\n            }\n            std::cout << \"Ошибка: M и N должны быть положительными, M·N не больше K. Повторите строку.\\n\";\n        }\n    }\n    const int m = std::stoi(rows[0].at(0)), n = std::stoi(rows[0].at(1));\n    if (rank >= m * n) return {};\n    return numbers(label(rank) + \"целые координаты X и Y: \", 2, 2, true);\n}\n\nvoid solve(int rank, int, const Row& row) {\n    int dims[2] = {0, 0};\n    if (rank == 0) {\n        dims[0] = std::stoi(row.at(0));\n        dims[1] = std::stoi(row.at(1));\n    }\n    MPI_Bcast(dims, 2, MPI_INT, 0, MPI_COMM_WORLD);\n    int periods[2] = {0, 1};\n    MPI_Comm cart;\n    MPI_Cart_create(MPI_COMM_WORLD, 2, dims, periods, 0, &cart);\n    if (cart != MPI_COMM_NULL) {\n        const int x = std::stoi(row.at(rank == 0 ? 2 : 0));\n        const int y = std::stoi(row.at(rank == 0 ? 3 : 1));\n        int target = -1;\n        if (x >= 0 && x < dims[0]) {\n            int coords[2] = {x, (y % dims[1] + dims[1]) % dims[1]};\n            MPI_Cart_rank(cart, coords, &target);\n        }\n        answer(rank, std::to_string(target));\n        MPI_Comm_free(&cart);\n    }\n}\n\nint main(int argc, char** argv) {\n    Task task = {\"MPIBegin94. Периодичность второго измерения: ранг координат X,Y.\",\n                 InputRanks::all, 2, false, false, readInput, solve};\n    return run(argc, argv, task);\n}\n",
  "96": "#include \"console_mpi.hpp\"\nusing namespace console_mpi;\n\nRow readInput(int rank, int, const Rows&) {\n    return numbers(label(rank) + \"одно вещественное A: \", 1, 1, false);\n}\n\nbool validSize(int size) { return size >= 4 && size % 2 == 0; }\n\nvoid solve(int rank, int size, const Row& row) {\n    int dims[2] = {2, size / 2}, periods[2] = {0, 1};\n    MPI_Comm cart;\n    MPI_Cart_create(MPI_COMM_WORLD, 2, dims, periods, 0, &cart);\n    int source, destination;\n    MPI_Cart_shift(cart, 1, 1, &source, &destination);\n    double value = valuesOf<double>(row).at(0), received = 0;\n    MPI_Status status;\n    MPI_Sendrecv(&value, 1, MPI_DOUBLE, destination, 0,\n                 &received, 1, MPI_DOUBLE, source, 0, cart, &status);\n    answer(rank, decimal(received));\n    MPI_Comm_free(&cart);\n}\n\nint main(int argc, char** argv) {\n    Task task = {\"MPIBegin96. Циклический сдвиг на 1 внутри каждой строки.\",\n                 InputRanks::all, 4, false, false, readInput, solve, nullptr, validSize};\n    return run(argc, argv, task);\n}\n",
  "100": "#include \"console_mpi.hpp\"\nusing namespace console_mpi;\n\nRow readInput(int rank, int, const Rows&) {\n    return numbers(label(rank) + \"одно целое A: \", 1, 1, true);\n}\n\nbool validSize(int size) { return size == 7 || size == 10 || size == 13; }\n\nvoid solve(int rank, int size, const Row& row) {\n    std::vector<std::vector<int>> adjacent(size);\n    auto edge = [&](int a, int b) {\n        adjacent[a].push_back(b);\n        adjacent[b].push_back(a);\n    };\n    for (int first = 1; first < size; first += 3) {\n        edge(first, first + 1);\n        edge(first, first + 2);\n        edge(first + 1, first + 2);\n        edge(0, first + 2);\n    }\n    std::vector<int> index(size), edges;\n    for (int r = 0; r < size; ++r) {\n        std::sort(adjacent[r].begin(), adjacent[r].end());\n        edges.insert(edges.end(), adjacent[r].begin(), adjacent[r].end());\n        index[r] = static_cast<int>(edges.size());\n    }\n    MPI_Comm graph;\n    MPI_Graph_create(MPI_COMM_WORLD, size, index.data(), edges.data(), 0, &graph);\n    int graphRank, count;\n    MPI_Comm_rank(graph, &graphRank);\n    MPI_Graph_neighbors_count(graph, graphRank, &count);\n    std::vector<int> neighbors(count);\n    MPI_Graph_neighbors(graph, graphRank, count, neighbors.data());\n    std::sort(neighbors.begin(), neighbors.end());\n\n    const int value = valuesOf<int>(row).at(0);\n    std::vector<int> received(size);\n    // Общий порядок рёбер гарантирует, что попарные MPI_Sendrecv не заблокируются.\n    for (int a = 0; a < size; ++a) {\n        for (int b = a + 1; b < size; ++b) {\n            if (graphRank != a && graphRank != b) continue;\n            const int other = graphRank == a ? b : a;\n            if (!std::binary_search(neighbors.begin(), neighbors.end(), other)) continue;\n            MPI_Status status;\n            MPI_Sendrecv(&value, 1, MPI_INT, other, 0,\n                         &received[other], 1, MPI_INT, other, 0, graph, &status);\n        }\n    }\n    Row result;\n    for (int neighbor : neighbors) result.push_back(std::to_string(received[neighbor]));\n    answer(rank, join(result));\n    MPI_Comm_free(&graph);\n}\n\nint main(int argc, char** argv) {\n    Task task = {\"MPIBegin100. Граф из треугольных лучей: обмен с соседями.\",\n                 InputRanks::all, 7, false, false, readInput, solve, nullptr, validSize};\n    return run(argc, argv, task);\n}\n"
};
